def shipping_cost(weight_kg, express=False):
    """Return the shipping cost in EUR for a parcel.

    The standard price is a 4.00 EUR base fee plus 1.75 EUR for each
    kilogram.  Express delivery doubles that calculated price.  The final
    amount (rather than intermediate values) is rounded to two decimals.
    """
    total = 4.00 + 1.75 * weight_kg
    if express:
        total *= 2
    return round(total, 2)

